def convertir_anciennes_reservations(apps, schema_editor):
    """Anciennes réservations (bus choisi + nombre de places) → une ligne par passager, même bus."""
    ReservationBus = apps.get_model("evenements", "ReservationBus")
    PassagerBus = apps.get_model("evenements", "PassagerBus")
    for resa in ReservationBus.objects.select_related("membre"):
        nom = resa.membre.nom_complet if resa.membre_id else "Passager"
        passagers = [PassagerBus(reservation=resa, nom=nom, est_titulaire=True, bus_numero=resa.bus_numero)]
        for i in range(2, (resa.nb_places or 1) + 1):
            passagers.append(
                PassagerBus(reservation=resa, nom=f"{nom} (accompagnant {i - 1})", bus_numero=resa.bus_numero)
            )
        PassagerBus.objects.bulk_create(passagers)
        resa.acceptee = True
        resa.save(update_fields=["acceptee"])


